package org.brightstats.stats;
import java.util.*;import org.apache.commons.math3.linear.*;

/** Exact deletion refits and prespecified model alternatives on a common source sample. */
public final class SemSensitivity {
 private SemSensitivity(){}
 public enum Unit { CASE, CLUSTER }
 public record InfluenceOptions(Unit unit,List<String> selectedUnits,int maximumRefits,FimlSem.Options estimator){public InfluenceOptions{Objects.requireNonNull(unit);selectedUnits=List.copyOf(selectedUnits);Objects.requireNonNull(estimator);if(maximumRefits<1||maximumRefits>2000||selectedUnits.stream().anyMatch(s->s==null||s.isBlank())||new HashSet<>(selectedUnits).size()!=selectedUnits.size())throw new IllegalArgumentException("Select distinct influence units and a maximum of 1–2,000 deletion refits.");}}
 public record Deletion(String unit,List<Integer> removedSourceRows,boolean usable,int remainingInformativeRows,Double likelihoodDisplacement,Double generalizedCookDistance,double[] estimates,double[] changes,double[] scaledChanges,String issue){public Deletion{removedSourceRows=List.copyOf(removedSourceRows);estimates=estimates.clone();changes=changes.clone();scaledChanges=scaledChanges.clone();}@Override public double[] estimates(){return estimates.clone();}@Override public double[] changes(){return changes.clone();}@Override public double[] scaledChanges(){return scaledChanges.clone();}}
 public record Influence(SemModel.Model model,InfluenceOptions options,String sourceDataSha256,String modelSha256,String unitAssignmentSha256,FimlSem.Fit reference,List<Deletion> deletions,int attempted,int successful,List<String> warnings){public Influence{deletions=List.copyOf(deletions);warnings=List.copyOf(warnings);}}
 public record Candidate(String name,SemModel.Model model,FimlSem.Options options){public Candidate{if(name==null||name.isBlank()||name.length()>120)throw new IllegalArgumentException("Name each specification (1–120 characters).");Objects.requireNonNull(model);Objects.requireNonNull(options);}}
 public record Alternative(String name,String modelSha256,boolean regular,Double aic,Double bic,Double deltaAic,Double deltaBic,FimlSem.Fit fit,String issue){}
 public record ParameterRange(String parameter,String locationSignature,int availableRegularFits,int totalSpecifications,double minimumEstimate,double maximumEstimate){}
 public record Multiverse(String sourceDataSha256,int suppliedRows,List<Integer> commonSourceRows,boolean completeCases,List<Candidate> specifications,List<Alternative> alternatives,List<ParameterRange> comparableParameterRanges,List<String> warnings){public Multiverse{commonSourceRows=List.copyOf(commonSourceRows);specifications=List.copyOf(specifications);alternatives=List.copyOf(alternatives);comparableParameterRanges=List.copyOf(comparableParameterRanges);warnings=List.copyOf(warnings);}}
 public static Influence influence(double[][] data,List<String> clusterIds,SemModel.Model model,InfluenceOptions options,java.util.function.IntConsumer progress){
  var reference=FimlSem.fit(data,model,options.estimator());if(!reference.converged()||!reference.locallyIdentified()||reference.boundary())throw new IllegalArgumentException("Influence comparisons require a regular, converged interior reference fit.");int q=model.parameters().size();if(q<1||q>80)throw new IllegalArgumentException("Influence analysis supports 1–80 free parameters.");LinkedHashMap<String,List<Integer>> units=new LinkedHashMap<>();if(options.unit()==Unit.CLUSTER)units=ClusterSem.groups(data,clusterIds);else for(int i=0;i<data.length;i++)units.put(Integer.toString(i+1),List.of(i));final var availableUnits=units;List<String> selected=options.selectedUnits().isEmpty()?List.copyOf(units.keySet()):options.selectedUnits();if(selected.size()>options.maximumRefits()||selected.stream().anyMatch(s->!availableUnits.containsKey(s)))throw new IllegalArgumentException("Requested deletion units are unknown or exceed the declared refit cap; explicitly select fewer units.");double[] point=reference.estimates();double[][] covariance=reference.parameterCovariance();double[][] correlation=new double[q][q];for(int i=0;i<q;i++)for(int j=0;j<q;j++)correlation[i][j]=covariance[i][j]/Math.sqrt(covariance[i][i])/Math.sqrt(covariance[j][j]);RealMatrix precision=new CholeskyDecomposition(new Array2DRowRealMatrix(correlation),1e-8,1e-12).getSolver().getInverse();var likelihood=new SemObservedLikelihood(data,model);List<Deletion> results=new ArrayList<>();int success=0;
  for(String unit:selected){Matrices.interrupted();List<Integer> removed=units.get(unit);Set<Integer> remove=new HashSet<>(removed);double[] estimates=new double[q],changes=new double[q],scaled=new double[q];Arrays.fill(estimates,Double.NaN);Arrays.fill(changes,Double.NaN);Arrays.fill(scaled,Double.NaN);boolean usable=false;int remaining=0;Double displacement=null,cook=null;String issue="";try{double[][] sample=new double[data.length-removed.size()][];int at=0;for(int i=0;i<data.length;i++)if(!remove.contains(i)){sample[at++]=data[i].clone();if(Arrays.stream(data[i]).anyMatch(Double::isFinite))remaining++;}var fit=FimlSem.fit(sample,model,options.estimator());usable=fit.converged()&&fit.locallyIdentified()&&!fit.boundary();if(!usable)issue="Deletion fit did not establish convergence, local identification and an interior solution";else{estimates=fit.estimates();double[] theta=estimates.clone();for(int j=0;j<q;j++){changes[j]=point[j]-estimates[j];scaled[j]=changes[j]/Math.sqrt(covariance[j][j]);theta[j]/=model.parameters().get(j).scale();}RealVector difference=new ArrayRealVector(scaled);cook=difference.dotProduct(precision.operate(difference))/q;double deletedPointFullLL=-likelihood.observations*likelihood.evaluate(theta).value();displacement=2*(reference.logLikelihood()-deletedPointFullLL);success++;}}catch(java.util.concurrent.CancellationException cancelled){throw cancelled;}catch(RuntimeException invalid){issue=Objects.toString(invalid.getMessage(),invalid.getClass().getSimpleName());}results.add(new Deletion(unit,removed.stream().map(i->i+1).toList(),usable,remaining,displacement,cook,estimates,changes,scaled,issue));if(progress!=null)progress.accept(results.size());}
  return new Influence(model,options,AnalysisIdentity.data(data,observedNames(model)),AnalysisIdentity.model(model),AnalysisIdentity.model(units),reference,results,results.size(),success,List.of("Exact leave-one-case or whole-cluster deletion refits. Source row numbers are one-based input rows; cluster deletion removes every member together. All attempted refits, including failures, remain visible. No rows are automatically removed from your working project.","Changes are reference minus deletion estimates, scaled by the full-reference model SE. Generalized Cook distance uses the full-reference parameter covariance and parameter count. Likelihood displacement evaluates the deletion estimate on the original full data. Negative displacement can reveal a better full-data optimum and must be investigated, not clipped.","Influence measures are descriptive model-conditional sensitivity diagnostics, not automatic outlier labels or deletion recommendations. The reference likelihood retains its Gaussian ignorable-missingness assumptions. Whole-cluster deletion does not itself turn marginal-model SE into cluster-robust SE."));
 }
 public static Multiverse multiverse(double[][] data,List<Candidate> candidates,boolean completeCases,java.util.function.IntConsumer progress){
  if(candidates==null||candidates.size()<2||candidates.size()>20||new HashSet<>(candidates.stream().map(Candidate::name).toList()).size()!=candidates.size())throw new IllegalArgumentException("Provide 2–20 distinctly named model specifications.");List<String> names=observedNames(candidates.getFirst().model());for(var candidate:candidates)if(!observedNames(candidate.model()).equals(names))throw new IllegalArgumentException("All specifications must use the same observed variable names/order for comparable likelihoods.");List<Integer> rows=new ArrayList<>();for(int i=0;i<data.length;i++){if(data[i].length!=names.size())throw new IllegalArgumentException("Common source dimensions differ from observed model order.");if(Arrays.stream(data[i]).anyMatch(Double::isInfinite))throw new IllegalArgumentException("Infinite source values are invalid.");if(!completeCases||Arrays.stream(data[i]).allMatch(Double::isFinite))rows.add(i);}double[][] common=new double[rows.size()][];for(int i=0;i<common.length;i++)common[i]=data[rows.get(i)].clone();List<Alternative> alternatives=new ArrayList<>();double bestAic=Double.POSITIVE_INFINITY,bestBic=Double.POSITIVE_INFINITY;
  for(var candidate:candidates){Matrices.interrupted();FimlSem.Fit fit=null;boolean regular=false;String issue="";try{fit=FimlSem.fit(common,candidate.model(),candidate.options());regular=fit.converged()&&fit.locallyIdentified()&&!fit.boundary();if(!regular)issue="Nonregular fit: compare provisionally, excluded from AIC/BIC ranking";else{bestAic=Math.min(bestAic,fit.aic());bestBic=Math.min(bestBic,fit.bic());}}catch(java.util.concurrent.CancellationException cancelled){throw cancelled;}catch(RuntimeException invalid){issue=Objects.toString(invalid.getMessage(),invalid.getClass().getSimpleName());}alternatives.add(new Alternative(candidate.name(),AnalysisIdentity.model(candidate.model()),regular,regular?fit.aic():null,regular?fit.bic():null,null,null,fit,issue));if(progress!=null)progress.accept(alternatives.size());}
  List<Alternative> ranked=new ArrayList<>();Map<String,List<Double>> estimates=new LinkedHashMap<>();Map<String,String> labels=new HashMap<>(),signatures=new HashMap<>();for(var candidate:alternatives){ranked.add(new Alternative(candidate.name(),candidate.modelSha256(),candidate.regular(),candidate.aic(),candidate.bic(),candidate.regular()?candidate.aic()-bestAic:null,candidate.regular()?candidate.bic()-bestBic:null,candidate.fit(),candidate.issue()));if(candidate.regular())for(int j=0;j<candidate.fit().model().parameters().size();j++){var parameter=candidate.fit().model().parameters().get(j);String signature=parameterSignature(candidate.fit().model(),parameter),key=parameter.name()+"|"+signature;labels.put(key,parameter.name());signatures.put(key,signature);estimates.computeIfAbsent(key,k->new ArrayList<>()).add(candidate.fit().estimates()[j]);}}
  List<ParameterRange> ranges=new ArrayList<>();estimates.forEach((key,values)->ranges.add(new ParameterRange(labels.get(key),signatures.get(key),values.size(),candidates.size(),values.stream().mapToDouble(Double::doubleValue).min().orElseThrow(),values.stream().mapToDouble(Double::doubleValue).max().orElseThrow())));return new Multiverse(AnalysisIdentity.data(common,names),data.length,rows.stream().map(i->i+1).toList(),completeCases,candidates,ranked,ranges,List.of("Specifications are evaluated on one immutable common observed-variable order and common selected source sample. Complete-case selection, if requested, happens once for all specifications. Missing-data FIML otherwise uses the same original observed patterns. No candidate is silently dropped or replaced.","AIC/BIC differences rank only regular fits within this prespecified candidate set; no universal best-model or causal-validity claim is made. Failed/nonregular alternatives remain visible. Confidence intervals/P values within each fit are not adjusted for exploration and are not pooled.","Estimate ranges group only identical parameter names and explicit named-variable location signatures. Matching labels alone do not establish a common estimand. Different scales, latent interpretations or scientific assumptions still require substantive review; displayed ranges are not model-averaged inference."));
 }
 static List<String> observedNames(SemModel.Model model){return Arrays.stream(model.observed()).mapToObj(i->model.variables().get(i)).toList();}
 public static String parameterSignature(SemModel.Model model,SemModel.Parameter parameter){return parameter.locations().stream().map(l->l.kind()+":"+model.variables().get(l.row())+(l.kind()==SemModel.Kind.INTERCEPT?"":":"+model.variables().get(l.column()))).sorted().reduce((a,b)->a+";"+b).orElseThrow();}
}
